  "diagrams": [
    {
      "id": "dependencies",
      "title": "Dependencies",
      "shows": "services, grouped by stack; `depends_on` and declared dependencies, labelled with the network each crosses",
      "kinds": [
        "depends_on"
      ],
      "note": "a declared dependency is marked as declared: it is what an operator said, and this diagram draws it beside what was observed without merging the two (§14 rule 1). An edge with no network to cross is drawn direct and marked — the dependency is real and the path to it is not visible here (§8).",
      "nodeThreshold": 60,
      "cap": 24,
      "groupByStack": true,
      "tags": [
        {
          "member": "declared",
          "label": "Declared",
          "tone": "info",
          "note": "an operator said this dependency exists (§14 rule 1)"
        },
        {
          "member": "observed",
          "label": "Observed",
          "tone": "neutral",
          "note": "the scan resolved it from the compose file"
        },
        {
          "member": "direct",
          "label": "No shared network",
          "tone": "warn",
          "note": "the dependency is real and no network in this scan explains how it is reached (§8)"
        }
      ]
    },
    {
      "id": "networks",
      "title": "Networks",
      "shows": "services and networks; membership, with arrowheads carrying flow and styling carrying its provenance",
      "kinds": [
        "network"
      ],
      "note": "a line here is membership, not a relation: two services on one network can reach each other and that is all this says (§16). An arrowhead means something crossed the network — a dependency — and a dashed leg means every dependency across it was declared rather than observed.",
      "nodeThreshold": 60,
      "cap": 12,
      "tags": [
        {
          "member": "to-network",
          "label": "Outbound",
          "tone": "neutral",
          "note": "this service is the dependent"
        },
        {
          "member": "to-service",
          "label": "Inbound",
          "tone": "neutral",
          "note": "something else on that network depends on it"
        },
        {
          "member": "both",
          "label": "Both",
          "tone": "neutral",
          "note": ""
        },
        {
          "member": "observed",
          "label": "Observed",
          "tone": "info",
          "note": "compose states it"
        },
        {
          "member": "declared",
          "label": "Declared",
          "tone": "neutral",
          "note": "only a sidecar states it — drawn dashed"
        },
        {
          "member": "both",
          "label": "Observed and declared",
          "tone": "info",
          "note": ""
        }
      ]
    },
    {
      "id": "ingress",
      "title": "Ingress paths",
      "shows": "outside → hostname → tunnel or router → origin → service, one path per route, with the gate drawn on the path",
      "kinds": [
        "ingress"
      ],
      "note": "the reserved colour marks a path from outside with no gate this scan could find. A tunnel whose origin resolved to another service is drawn through that hop; every other origin keeps its direct edge, because an invented hop would be a claim about the path (§9).",
      "nodeThreshold": 80,
      "cap": 24,
      "tags": [
        {
          "member": "ungated",
          "label": "No gate found",
          "tone": "alert",
          "note": "reachable from outside with nothing in front of it — the one reserved colour (§22.1)"
        }
      ]
    },
    {
      "id": "identity",
      "title": "Identity and auth",
      "shows": "providers, applications, outposts, proxies and services; which application protects which service, at what strength",
      "kinds": [
        "auth"
      ],
      "note": "an unmatched application or router is drawn unattached rather than hidden: a record that protects nothing this scan found is the finding (§11, §12). An edge's label is the strength of the match, and `name` is the weakest of them (§4.3).",
      "nodeThreshold": 80,
      "cap": 24,
      "tags": [
        {
          "member": "address",
          "label": "By address",
          "tone": "good",
          "note": "the provider's address resolved to this service"
        },
        {
          "member": "hostname",
          "label": "By hostname",
          "tone": "info",
          "note": "a declared hostname matched"
        },
        {
          "member": "name",
          "label": "By name",
          "tone": "neutral",
          "note": "names matched, and nothing stronger did"
        },
        {
          "member": "unattached",
          "label": "Unattached",
          "tone": "warn",
          "note": "a provider record that matched nothing in this fleet, drawn rather than hidden (§11, §12)"
        }
      ]
    }
  ],
